// offerGroups splits the offers by service, keeping their order.
func offerGroups(offers []ConnectOffer) [][]ConnectOffer {
	var out [][]ConnectOffer
	for _, o := range offers {
		if n := len(out); n > 0 && out[n-1][0].Service == o.Service {
			out[n-1] = append(out[n-1], o)
		} else {
			out = append(out, []ConnectOffer{o})
		}
	}
	return out
}

func offerKeys(g []ConnectOffer) string {
	keys := make([]string, 0, len(g))
	for _, o := range g {
		keys = append(keys, o.Key)
	}
	return strings.Join(keys, " · ")
}

func connectTitle(ctx context.Context, d ServiceData) string {
	if len(d.ConnectOffers) == 0 {
		return t(ctx, "connect.no_targets")
	}
	return ""
}

